#include <iostream>
#include <array>
#include <algorithm>
#include <functional>

// Custom functor maintaining call count state
struct GreaterWithCounter {
    int comparisons = 0;
    bool operator()(int a, int b) {
        ++comparisons;
        return a > b;
    }
};

int main() {
    std::array<int, 6> data{15, 3, 42, 8, 99, 24};

    // Standard minmax_element
    auto [minIt, maxIt] = std::minmax_element(data.begin(), data.end());
    std::cout << "Min element: " << *minIt << "\n";
    std::cout << "Max element: " << *maxIt << "\n";

    // Using predefined standard functor std::greater<int>
    auto [maxCustom, minCustom] = std::minmax_element(data.begin(), data.end(), std::greater<int>());
    std::cout << "Under greater: first is " << *maxCustom << ", second is " << *minCustom << "\n";

    return 0;
}

#include <iostream>
#include <array>
#include <numeric>
#include <algorithm>

// Free binary function for sum of squares
int sumSquaresFunc(int total, int value) {
    return total + value * value;
}

// Generic binary functor for sum of squares
template <typename T>
struct SumSquaresFunctor {
    T operator()(const T& total, const T& value) const {
        return total + value * value;
    }
};

int main() {
    const std::array<int, 5> nums{1, 2, 3, 4, 5};

    // 1. Using a free function pointer with std::accumulate
    int resFunc = std::accumulate(nums.cbegin(), nums.cend(), 0, sumSquaresFunc);
    std::cout << "Using function pointer: " << resFunc << "\n";

    // 2. Using an instantiated functor with std::accumulate
    int resObj = std::accumulate(nums.cbegin(), nums.cend(), 0, SumSquaresFunctor<int>{});
    std::cout << "Using functor object: " << resObj << "\n";

    // 3. Using a lambda with std::accumulate
    int resLambda = std::accumulate(nums.cbegin(), nums.cend(), 0,
        [](int total, int value) { return total + value * value; });
    std::cout << "Using binary lambda: " << resLambda << "\n";

    // 4. Using std::for_each with capture-by-reference lambda
    int runningTotal = 0;
    std::for_each(nums.cbegin(), nums.cend(), [&runningTotal](int x) {
        runningTotal += x * x;
    });
    std::cout << "Using for_each with capture: " << runningTotal << "\n";

    return 0;
}
